const root=document.getElementById('fn-studio');
const page=document.getElementById('page');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>ICONS[name]||ICONS.Box;
const number=(n,d=2)=>Number.isFinite(Number(n))?Number(n).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const btn=(action,label,glyph='',attrs='',style='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${attrs}>${glyph?icon(glyph):''}${label}</button>`;
const ibtn=(action,label,glyph,attrs='')=>`<button type="button" class="icon-btn" data-action="${action}" aria-label="${esc(label)}" title="${esc(label)}" ${attrs}>${icon(glyph)}</button>`;
const badge=(label,type='')=>`<span class="badge ${type}">${label}</span>`;
const empty=(title,description,action='')=>`<div class="empty">${icon('FolderOpen')}<h3>${title}</h3><p>${description}</p>${action}</div>`;
const option=(value,label,current)=>`<option value="${esc(value)}"${String(value)===String(current)?' selected':''}>${esc(label)}</option>`;
const clockLabel=t=>`t = ${number(t,1)} s`;
let recovery='';
let state=initialState();
try { const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(saved&&saved.schema===1&&Array.isArray(saved.projects)&&saved.projects.length&&Array.isArray(saved.modules)&&saved.modules.length&&Array.isArray(saved.models)){state=saved;state.projects.forEach(p=>{if(p.run.status==='running')p.run.status='paused';});if(state.bench.run.status==='running')state.bench.run.status='paused';} } catch { recovery='上次原型记录无法读取，已打开内置示例。'; }
const ui={route:'home',theme:matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light',moduleTab:'drawing',selectedNode:'',selectedEdge:'',editorPort:'',category:'全部模块',moduleSearch:'',projectSearch:'',projectFilter:'all',projectView:'grid',bank:0,allBanks:false,variableSearch:'',onlyCommon:false,valueSearch:'',arrayVar:'system:form',codeKind:'runtime',designIndex:0,modelSearch:'',modelFilter:'all',modelTab:'parameters',benchTab:'results',settingsTab:'project',connectionTab:'variables',selectedConnector:'serial1',nodeDomain:'fluid',nodeTab:'definition',selectedRecord:'DEMO-003',runFilter:'all',pageGrid:false,placing:null,connecting:null,canvasMode:'select',floats:[],frontId:'',floatSerial:0,taskDrawer:false,selectedChart:'q',clipboard:null,showLibrary:false,compileOutput:'尚未检查。编辑后可检查括号结构或查看编译流程。',controlOutput:'控制脚本尚未预览。',connectionSearch:'',guideStep:0};
try {const savedUI=JSON.parse(localStorage.getItem(UI_KEY)||'null');if(savedUI){for(const key of ['theme','moduleTab','settingsTab','connectionTab','bank','pageGrid','codeKind','designIndex'])if(savedUI[key]!==undefined)ui[key]=savedUI[key];}}catch{}
if (['design','header'].includes(ui.moduleTab)) { ui.codeKind=ui.moduleTab; ui.moduleTab='code'; }
if (!['runtime','design','header'].includes(ui.codeKind)) ui.codeKind='runtime';
if (![0,1,2].includes(ui.designIndex)) ui.designIndex=0;
let modal=null,contextMenu=null,pointer=null,toastTimer,runInterval,undoStack=[],redoStack=[],lastTick=0;
const project=()=>state.projects.find(p=>p.id===state.activeProject)||state.projects[0];
const activePage=()=>project().pages.find(p=>p.id===project().activePage)||project().pages[0];
const mod=(id=state.selectedModule)=>state.modules.find(m=>m.id===id)||state.modules[0];
const instance=id=>project().pages.flatMap(p=>p.nodes).find(n=>n.id===id);
const moduleOf=n=>mod(n.moduleId);
const model=(id=state.selectedModel)=>state.models.find(m=>m.id===id);
const paramDefs=n=>PARAM_DEFS[moduleOf(n).kind]||[];
const pendingCount=n=>paramDefs(n).filter(f=>n.draft[f[0]]!==n.params[f[0]]).length+instanceCustomPending(n)+(n.draftModelId&&(n.draftModelId!==n.modelId||n.draftModelVersion!==n.modelVersion)?1:0);
const anyPending=()=>state.projects.reduce((sum,p)=>sum+p.pages.flatMap(p=>p.nodes).reduce((s,n)=>s+pendingCount(n),0),0);
const statusText=run=>({ready:'就绪',running:'运行中',paused:'已暂停',stopped:'已停止',completed:'已完成',failed:'失败'}[run.status]||'就绪');
function msg(text,error=false){const toast=document.getElementById('toast');toast.className='toast'+(error?' error':'');toast.innerHTML=icon(error?'Info':'CheckCircle2')+`<span>${esc(text)}</span>`;toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.hidden=true,3500);document.getElementById('announcement').textContent=text;}
function saveUI(){try{localStorage.setItem(UI_KEY,JSON.stringify({theme:ui.theme,moduleTab:ui.moduleTab,settingsTab:ui.settingsTab,connectionTab:ui.connectionTab,bank:ui.bank,pageGrid:ui.pageGrid,codeKind:ui.codeKind,designIndex:ui.designIndex}));}catch{}}
function markDirty(target){state.dirty=true;if(target)target.dirty=true;root.querySelectorAll("[data-float-save]").forEach(el=>el.textContent="草稿未保存");syncChrome();}
function saveAll(){
  const payload=clone(state);payload.dirty=false;payload.savedAt=new Date().toISOString();payload.projects.forEach(p=>p.dirty=false);payload.modules.forEach(m=>m.dirty=false);
  try{localStorage.setItem(STORAGE_KEY,JSON.stringify(payload));state.dirty=false;state.savedAt=payload.savedAt;state.projects.forEach(p=>p.dirty=false);state.modules.forEach(m=>m.dirty=false);syncChrome();updateFloatBodies();msg(`原型草稿已保存${anyPending()?` · ${anyPending()} 项参数待应用`:''}`);}
  catch{msg('浏览器未能保存，请通过“导出原型”保留当前内容。',true);}
}
function log(text,kind='INFO'){state.messages.unshift({time:new Date().toLocaleTimeString('zh-CN',{hour12:false}),kind,text});state.messages=state.messages.slice(0,80);}
function remember(){undoStack.push(clone(project().pages));if(undoStack.length>30)undoStack.shift();redoStack=[];}
function undo(redo=false){const from=redo?redoStack:undoStack,to=redo?undoStack:redoStack;if(!from.length)return;to.push(clone(project().pages));project().pages=from.pop();ui.selectedNode='';ui.selectedEdge='';ui.floats=ui.floats.filter(f=>instance(f.id));markDirty(project());render();msg(redo?'已重做':'已撤销');}
function navigate(route,options={}){if(!PAGE_META[route])route='home';Object.assign(ui,options);ui.route=route;contextMenu=null;ui.taskDrawer=false;if(location.hash!==`#${route}`)history.replaceState(null,'',`#${route}`);saveUI();render();page.scrollTop=0;}
function openProject(id){if(!state.projects.some(p=>p.id===id))return;state.activeProject=id;ui.selectedNode='';ui.floats=[];undoStack=[];redoStack=[];navigate('workbench');}
function openEditor(id,tab='drawing'){state.selectedModule=id;ui.editorPort='';ui.moduleTab=['design','header'].includes(tab)?'code':tab;if(['design','header'].includes(tab))ui.codeKind=tab;ui.arrayVar='system:form';navigate('editor');}
function heading(title,subtitle,actions='',eyebrow=''){return `<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p>${subtitle}</p></div><div class="row wrap">${actions}</div></div>`;}
function renderHeader(){document.getElementById('app-header').innerHTML=`<button class="brand" data-action="nav" data-route="home" aria-label="FluidNet Studio 首页"><span class="brand-mark">${icon('Network')}</span>FluidNet <span class="brand-sub">Studio</span></button><span class="header-rule"></span><button class="project-picker" data-action="project-picker">${icon('FolderOpen')}<span>${esc(project().name)}</span>${icon('ChevronDown')}</button>${badge('交互原型','warn')}<button class="header-search" data-action="page-map" aria-label="页面导航与快捷入口">${icon('Search')}<span>页面与操作</span><kbd>Ctrl K</kbd></button><span class="save-indicator" data-save-status></span>${btn('save','<span>保存原型</span>','Save','','header-save')}${ibtn('theme',ui.theme==='dark'?'切换浅色':'切换深色',ui.theme==='dark'?'Sun':'Moon')}${ibtn('nav','使用指南','CircleHelp','data-route="help"')}`;}
function renderRail(){const ids=['home','projects','workbench','modules','models','curves','runs','controls'];document.getElementById('app-rail').innerHTML=ids.map(id=>`${id==='modules'||id==='controls'?'<div class="rail-divider"></div>':''}<button type="button" class="rail-link${ui.route===id||ui.route==='editor'&&id==='modules'||ui.route==='nodes'&&id==='modules'?' active':''}" data-action="nav" data-route="${id}" title="${PAGE_META[id][2]}"${ui.route===id?' aria-current="page"':''}>${icon(PAGE_META[id][1])}<span>${PAGE_META[id][0]}</span></button>`).join('')+`<div class="rail-bottom"><div class="rail-divider"></div><button class="rail-link${ui.route==='settings'?' active':''}" data-action="nav" data-route="settings">${icon('Settings2')}<span>设置</span></button></div>`;}
function syncChrome(){
  const save=root.querySelector('[data-save-status]');if(save){save.classList.toggle('dirty',state.dirty);save.innerHTML=`<span class="dot"></span>${state.dirty?'有未保存修改':state.savedAt?'原型已保存':'示例已就绪'}`;}
  const run=project().run;const active=state.projects.filter(p=>p.run.status==='running'||p.run.status==='paused');
  document.getElementById('statusbar').innerHTML=`<span class="row gap-6"><span class="dot" style="color:var(--${run.status==='running'?'green':'muted'})"></span>${esc(project().name)} · ${statusText(run)}</span><span class="mono" data-live-time>${clockLabel(run.time)}</span>${active.length?`<button class="task-chip" data-action="tasks">${icon('Activity')} ${active.length} 个运行任务</button>`:''}<span class="optional">${anyPending()?`${anyPending()} 项参数待应用`:'参数已同步'}</span><span class="push"></span><button data-action="page-map" class="optional">页面导览</button><span class="prototype-label">交互原型 · 示例数据</span>`;
}
function render(){root.dataset.theme=ui.theme;renderHeader();renderRail();const views={home:renderHome,projects:renderProjects,workbench:renderWorkbench,modules:renderModules,editor:renderEditor,nodes:renderNodesPage,models:renderModels,curves:renderCurves,runs:renderRuns,controls:renderControls,settings:renderSettings,help:renderHelp};page.innerHTML=(views[ui.route]||renderHome)();renderFloats();syncChrome();renderDialog(false);requestAnimationFrame(resizeCharts);if(recovery){msg(recovery,true);recovery='';}}
function thumbnail(p){return `<svg viewBox="0 0 1100 470" role="img" aria-label="${esc(p.name)}管网预览">${networkMarkup(p.pages[0],true)}</svg>`;}
function projectCard(p){return `<article class="project-card"><button class="project-preview" data-action="open-project" data-id="${p.id}" aria-label="打开 ${esc(p.name)}">${thumbnail(p)}${badge(p.id===state.activeProject?'当前项目':'示例','')}</button><div class="project-info"><h3>${esc(p.name)}</h3><div class="meta"><span>${p.pages.length} 张画布</span><span>·</span><span>${p.pages.reduce((s,c)=>s+c.nodes.length,0)} 个设备</span><span>·</span><span>液态水</span></div><div class="row spread"><small class="muted">${p.dirty?'草稿有修改':esc(p.modified||'示例项目')}</small><div class="row gap-6">${ibtn('duplicate-project','复制项目','Copy',`data-id="${p.id}"`)}${btn('open-project','打开','ArrowUpRight',`data-id="${p.id}"`,'small')}</div></div></div></article>`;}
function renderHome(){return `<div class="page-shell">${heading('工作从这里开始','继续建模，或从一个验证过操作流程的示例开始。',btn('import','导入原型','Upload')+btn('new-project','新建项目','Plus','','primary'),'FLUIDNET WORKSPACE')}<div class="home-main"><div class="stack gap-20"><section><div class="section-title"><h2>最近项目</h2>${btn('nav','全部项目','ChevronRight','data-route="projects"','ghost small')}</div><div class="project-grid">${state.projects.slice(0,3).map(projectCard).join('')}</div><div class="home-note"><span class="note-icon">${icon('MousePointer2')}</span><div class="grow"><strong>从设备到系统，一条完整的工作路径</strong><p>定义模块 → 保存型号 → 项目建模 → 调参运行 → 曲线对照</p></div>${btn('guided-demo','开始体验','ArrowRight','','ghost')}</div></section><section class="panel"><div class="panel-head"><h2>最近使用的模块</h2>${btn('nav','模块库','ArrowUpRight','data-route="modules"','ghost small')}</div>${['valve','pump','exchanger','tank'].map(id=>{const m=mod(id);return `<div class="list-row"><span class="object-icon">${icon(m.icon)}</span><div class="grow"><strong>${m.name}</strong><small>${m.code} · ${m.ports.length} 个端口 · ${m.channels.length} 条内部通路</small></div>${badge('v'+m.version)}${btn('edit-module','编辑定义','Pencil',`data-id="${id}"`,'ghost small')}</div>`;}).join('')}</section></div><aside class="home-aside stack"><section class="panel"><div class="panel-head"><h2>快捷入口</h2>${icon('Grid2X2')}</div><div class="quick-list">${[['new-module','新建算法模块','Box'],['nav','管理设备型号','Database','models'],['nav','查看运行记录','History','runs'],['nav','页面与使用指南','BookOpen','help']].map(([act,label,i,r])=>`<button data-action="${act}" ${r?`data-route="${r}"`:''}>${icon(i)}<span class="grow">${label}</span>${icon('ChevronRight')}</button>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>消息与任务</h2>${badge('本地原型')}</div><div class="timeline">${state.messages.slice(0,3).map(m=>`<div class="timeline-item"><span class="timeline-point">${icon('CheckCircle2')}</span><div>${esc(m.text)}<small>${m.time} · ${m.kind}</small></div></div>`).join('')}</div></section><section class="panel"><div class="panel-body stack"><div class="row">${icon('Info')}<strong>当前体验范围</strong></div><p class="muted" style="font-size:12px">页面、数据编辑、型号应用与运行控制均可交互。计算使用示例数据。</p>${btn('page-map','查看全部页面','LayoutDashboard','','small')}</div></section></aside></div></div>`;}
function renderProjects(){let list=state.projects.filter(p=>(p.name+p.description).toLowerCase().includes(ui.projectSearch.toLowerCase()));if(ui.projectFilter==='current')list=list.filter(p=>p.id===state.activeProject);return `<div class="page-shell">${heading('项目管理','管理项目草稿、示例与画布；运行记录独立保存。',btn('import','导入原型','Upload')+btn('new-project','新建项目','Plus','','primary'))}<div class="filterbar"><label class="search">${icon('Search')}<input aria-label="搜索项目" data-filter="projectSearch" placeholder="搜索项目名称" value="${esc(ui.projectSearch)}"></label><div class="segmented">${[['all','全部项目'],['current','当前项目']].map(([k,v])=>`<button data-action="project-filter" data-value="${k}" class="${ui.projectFilter===k?'active':''}">${v}</button>`).join('')}</div><span class="push"></span><span class="muted">${list.length} 个项目</span><div class="segmented">${['grid','list'].map(k=>`<button aria-label="${k==='grid'?'卡片视图':'列表视图'}" data-action="project-view" data-value="${k}" class="${ui.projectView===k?'active':''}">${icon(k==='grid'?'Grid2X2':'List')}</button>`).join('')}</div></div><div id="project-results" class="project-grid${ui.projectView==='list'?' project-list-view':''}">${list.map(projectCard).join('')||empty('没有匹配的项目','换个关键词，或新建一个项目。')}</div><div class="home-note"><span class="note-icon">${icon('Folder')}</span><div class="grow"><strong>项目草稿保存在浏览器中</strong><p>“保存原型”会保留项目、模块、型号与界面状态，也可以导出一份原型数据备份。</p></div>${btn('export','导出原型','Download','data-format="prototype"','ghost')}</div></div>`;}
function renderModules(){const categories=['全部模块',...new Set(state.modules.map(m=>m.category))];let list=state.modules.filter(m=>(ui.category==='全部模块'||m.category===ui.category)&&(m.name+m.code).toLowerCase().includes(ui.moduleSearch.toLowerCase()));return `<div class="page-shell">${heading('模块库','定义可复用的设备：图形、端口、通路、变量与算法。',btn('nav','节点定义','Waypoints','data-route="nodes"')+btn('new-module','新建模块','Plus','','primary'))}<div class="split-view"><aside class="side-nav"><div class="side-caption">模块分类</div>${categories.map(c=>`<button data-action="module-category" data-value="${c}" class="${ui.category===c?'active':''}">${icon(c==='全部模块'?'Boxes':'Folder')}<span>${c}</span><small class="push muted">${c==='全部模块'?state.modules.length:state.modules.filter(m=>m.category===c).length}</small></button>`).join('')}<div class="spacer"></div><button data-action="nav" data-route="nodes">${icon('Waypoints')}节点与端口定义</button><button data-action="page-map">${icon('LayoutDashboard')}页面导航</button></aside><div><div class="filterbar"><label class="search">${icon('Search')}<input data-filter="moduleSearch" aria-label="搜索模块" placeholder="名称或模块标识" value="${esc(ui.moduleSearch)}"></label><span class="push muted">${list.length} 个模块</span>${btn('compile-preview','批量检查预览','CheckCheck','','small')}</div><div id="module-results" class="module-grid">${list.map(m=>`<article class="module-card"><div class="row"><span class="object-icon">${icon(m.icon)}</span><div class="grow"><h3>${esc(m.name)}</h3><small class="muted mono">${m.code}</small></div>${badge('v'+m.version)}</div><p>${esc(m.description)}</p><div class="stat-line"><span>${m.ports.length} 个端口</span><span>${m.channels.length} 条通路</span><span>${m.variables.length} 个变量</span></div><div class="card-footer">${btn('edit-module','编辑模块','Pencil',`data-id="${m.id}"`,'small')}<span class="push"></span>${ibtn('insert-module','插入项目 '+m.name,'Plus',`data-id="${m.id}"`)}</div></article>`).join('')||empty('没有匹配的模块','尝试其他分类或关键词。')}</div></div></div></div>`;}
function symbol(n,mini=false){const kind=moduleOf(n).kind;let s='';const stroke='var(--muted)',fill='var(--surface)';if(kind==='junction')s=`<circle r="5" fill="var(--orange)"/>`;else if(kind==='source')s=`<circle r="17" fill="var(--blue-soft)" stroke="var(--blue)" stroke-width="1.3"/><text y="4" text-anchor="middle" font-size="13" fill="var(--blue)">P</text>`;else if(kind==='pump')s=`<circle r="18" fill="var(--soft)" stroke="${stroke}" stroke-width="1.3"/><path d="M -5 -9 L 10 0 L -5 9 Z" fill="none" stroke="${stroke}" stroke-width="1.5"/><path d="M -13 22 H 13" stroke="${stroke}" stroke-width="2"/>`;else if(kind==='valve'||kind==='check')s=`<path d="M -15 -10 L 15 10 V -10 L -15 10 Z" fill="${fill}" stroke="var(--accent)" stroke-width="1.4"/>${kind==='check'?'<path d="M 0 -13 V 13" stroke="var(--accent)"/>':''}`;else if(kind==='pipe')s=`<rect x="-22" y="-5" width="44" height="10" rx="2" fill="${fill}" stroke="var(--accent)" stroke-width="1.3"/>`;else if(kind==='tank')s=`<rect x="-20" y="-28" width="40" height="56" rx="7" fill="var(--blue-soft)" stroke="${stroke}" stroke-width="1.3"/><path d="M -18 0 Q -9 -5 0 0 T 18 0" fill="none" stroke="var(--blue)"/>`;else if(kind==='exchanger')s=`<rect x="-29" y="-32" width="58" height="64" rx="5" fill="${fill}" stroke="${stroke}"/><path d="M -25 -17 H 23 M -25 17 H 23 M -10 -23 L 10 23 M 0 -23 L 20 23" stroke="var(--orange)" fill="none"/>`;else s=`<rect x="-18" y="-18" width="36" height="36" rx="6" fill="var(--soft)" stroke="${stroke}"/><text y="4" text-anchor="middle" fill="var(--text)" font-size="11">${kind==='heater'?'Q':kind==='pid'?'PID':kind==='sensor'?'F':'ƒ'}</text>`;return `<g transform="rotate(${n.rotation||0})">${s}</g>`;}
function portOffset(n,p){if(moduleOf(n).kind==='source')return {x:/^B[24](?:-|$)/.test(n.id)?-28:28,y:0};if(moduleOf(n).kind==='junction'){const flip=/^N2(?:-|$)/.test(n.id)?-1:1;return p.id==='in0'?{x:-24*flip,y:0}:{x:24*flip,y:p.id==='out0'?-18:18};}return {x:p.direction==='in'?-32:32,y:moduleOf(n).kind==='exchanger'?(p.id.endsWith('0')?-19:19):0};}
function endpoint(pg,nodeId,portId){const n=pg.nodes.find(n=>n.id===nodeId);if(!n)return null;const p=moduleOf(n).ports.find(p=>p.id===portId);if(!p)return null;const d=portOffset(n,p);const a=(n.rotation||0)*Math.PI/180;return {x:n.x+d.x*Math.cos(a)-d.y*Math.sin(a),y:n.y+d.x*Math.sin(a)+d.y*Math.cos(a),node:n,port:p};}
function routeLine(a,b){const mid=(a.x+b.x)/2;return Math.abs(a.y-b.y)<2?`M ${a.x} ${a.y} H ${b.x}`:`M ${a.x} ${a.y} H ${mid} V ${b.y} H ${b.x}`;}
function flowFor(n){const v=project().run.values;return /[VL]1/.test(n.id)?v.a:/[VL]2/.test(n.id)?v.b:v.q;}
function networkMarkup(pg,mini=false){const lines=pg.edges.map(([id,a,ap,b,bp])=>{const e1=endpoint(pg,a,ap),e2=endpoint(pg,b,bp);if(!e1||!e2)return '';const d=routeLine(e1,e2);return `<path d="${d}" class="net-line${ui.selectedEdge===id?' selected':''}"/>${mini?'':`<path d="${d}" class="net-hit" data-edge="${id}" role="button" aria-label="连接 ${a} 到 ${b}" tabindex="0"/>`}`;}).join('');
  const nodes=pg.nodes.map(n=>{const m=moduleOf(n);return `<g transform="translate(${n.x},${n.y})" class="net-node${!mini&&ui.selectedNode===n.id?' selected':''}" ${mini?'':`data-node="${n.id}" tabindex="0" role="button" aria-label="${esc(n.id+' '+n.name)}"`}><rect class="node-hit" x="-28" y="-35" width="56" height="101" fill="transparent" pointer-events="all"/><rect class="node-selection" x="-27" y="-28" width="54" height="56" rx="5"/>${portStubs(n)}${symbol(n,mini)}${!mini&&project().run.history.length&&ui.pageGrid!==null?`<text class="node-reading" x="0" y="-43" text-anchor="middle">${number(flowFor(n),3)}</text>`:''}${m.ports.map(p=>{const offset=portOffset(n,p),connected=pg.edges.some(e=>(e[1]===n.id&&e[2]===p.id)||(e[3]===n.id&&e[4]===p.id));return `<g transform="rotate(${n.rotation||0})"><g class="port-group${ui.connecting?.nodeId===n.id&&ui.connecting?.portId===p.id?' pending':''}" ${mini?'':`data-port-node="${n.id}" data-port-id="${p.id}" role="button" aria-label="${esc(n.id+' '+p.label)}" tabindex="0"`}><title>${esc(n.id+' · '+p.label+' · '+DOMAINS[p.domain].label)}${connected?' · 已连接':''}</title><circle cx="${offset.x}" cy="${offset.y}" r="${mini?3:3.5}" class="net-port${connected?' connected':''}"/>${mini?'':`<circle cx="${offset.x}" cy="${offset.y}" r="10" class="port-hit"/>`}</g></g>`;}).join('')}${mini?'':`<text class="node-code" x="0" y="44" text-anchor="middle">${esc(n.id)}</text><text class="node-name" x="0" y="60" text-anchor="middle">${esc(n.name)}</text>${quickCanvasMarkup(n,m)}`}</g>`;}).join('');return lines+nodes;}
function renderWorkbench(){const p=project(),pg=activePage(),selected=instance(ui.selectedNode);return `<div class="workbench${ui.showLibrary?' show-library':''}"><aside class="canvas-library"><div class="library-heading"><strong>模块库</strong><small class="muted">${state.modules.length} 类</small></div><label class="search">${icon('Search')}<input placeholder="查找模块" aria-label="画布模块搜索" data-filter="canvasModuleSearch"></label><div class="library-scroll" id="canvas-library-list">${libraryMarkup()}</div><div class="selected-properties" id="selected-properties">${propertiesMarkup(selected)}</div></aside><div class="canvas-column"><div class="canvas-bar"><div class="canvas-pages">${pgTabs()}${ibtn('new-canvas','新增画布','Plus')}</div><div class="canvas-tools">${ibtn('toggle-library','模块库开关','PanelLeftClose')}${ibtn('select-mode','选择设备','MousePointer2')}${ibtn('connect-mode','连接端口','Cable')}<span class="tool-divider"></span>${ibtn('undo','撤销 Ctrl+Z','Undo2',undoStack.length?'':'disabled')}${ibtn('redo','重做 Ctrl+Y','Redo2',redoStack.length?'':'disabled')}${ibtn('fit','适应画布','Scan')}${ibtn('grid','显示点阵','Grid2X2','class="optional"')}${ibtn('validate','检查连接','ListChecks')}</div></div><div class="canvas-area${ui.pageGrid?' grid':''}" id="network-area"><div class="canvas-caption"><span>${esc(pg.name)}</span><span class="muted">${p.run.history.length?'质量流量 · kg/s':'单击选择 · 双击参数'}</span>${badge('液态水','blue')}</div>${pg.nodes.length?`<svg id="network" class="network-svg" viewBox="${-35-pg.pan[0]} ${-5-pg.pan[1]} ${1140/(pg.zoom||1)} ${510/(pg.zoom||1)}" role="group" aria-label="${esc(p.name+' '+pg.name+' 管网画布')}">${networkMarkup(pg)}</svg>`:`<div class="empty" style="padding-top:18%">${icon('Network')}<h3>在这里搭建新系统</h3><p>从左侧选择模块，再点击画布放置设备。</p>${btn('insert-defaults','放入泵阀示例','Plus','','primary')}</div><svg id="network" class="network-svg" viewBox="-35 -5 1140 510" style="position:absolute;inset:0" aria-label="空画布"></svg>`}<div class="runbar" aria-label="主系统运行控制"><button data-action="save" title="保存项目草稿">${icon('Save')}保存</button><button data-action="run-project" data-command="run" class="go" ${p.run.status==='running'?'disabled':''}>${icon('Play')}<span>${p.run.status==='paused'?'继续':'运行'}</span></button><button data-action="run-project" data-command="pause" ${p.run.status==='running'?'':'disabled'}>${icon('Pause')}暂停</button><button data-action="run-project" data-command="step" ${p.run.status==='running'?'disabled':''}>${icon('StepForward')}单步</button><button data-action="run-project" data-command="stop" ${['ready','stopped'].includes(p.run.status)?'disabled':''}>${icon('Square')}停止</button><span class="spacer"></span><button data-action="nav" data-route="curves">${icon('Activity')}曲线</button></div><div class="canvas-bottom"><span data-canvas-hint>${ui.placing?'点击画布放置 '+mod(ui.placing).name:ui.connecting?'选择另一个空闲端口 · Esc 取消':'双击设备编辑参数 · 拖动空白处平移'}</span><div class="zoom">${ibtn('zoom-out','缩小','Minus')}<span>${Math.round(pg.zoom*100)}%</span>${ibtn('zoom-in','放大','Plus')}</div></div></div><div class="canvas-info"><span>主系统 · ${statusText(p.run)}</span><span class="mono" data-live-time>${clockLabel(p.run.time)}</span><span class="optional">${pg.nodes.length} 个设备 · ${pg.edges.length} 条连接</span><span class="push"></span>${btn('nav','项目设置','Settings2','data-route="settings"','ghost small')}${btn('nav','控制逻辑','Code2','data-route="controls"','ghost small')}</div></div></div>`;}
function pgTabs(){return project().pages.map(p=>`<button data-action="canvas-tab" data-id="${p.id}" class="${p.id===project().activePage?'active':''}">${esc(p.name)}</button>`).join('');}
function libraryMarkup(query=''){return [...new Set(state.modules.map(m=>m.category))].map(c=>{const modules=state.modules.filter(m=>m.category===c&&(m.name+m.code).toLowerCase().includes(query.toLowerCase()));return modules.length?`<div class="library-caption">${icon('ChevronDown')}${c}</div>${modules.map(m=>`<button class="library-item${ui.placing===m.id?' active':''}" data-action="place-module" data-id="${m.id}" draggable="true" data-drag-module="${m.id}">${icon(m.icon)}<span>${m.name}</span><small>${m.code.slice(0,2)}</small></button>`).join('')}`:'';}).join('');}
function propertiesMarkup(n){if(n){const m=moduleOf(n);return `<div class="row spread"><h3>对象属性</h3>${badge(n.id,'warn')}</div><dl><dt>名称</dt><dd>${esc(n.name)}</dd><dt>模块</dt><dd>${esc(m.name)}</dd><dt>型号</dt><dd>${esc(model(n.modelId)?.name||'自定义参数')}</dd>${paramDefs(n).slice(0,2).map(f=>`<dt>${f[1].replace('阀门','').replace('流量系数 ','')}</dt><dd>${number(n.params[f[0]],f[0]==='opening'?0:2)} ${f[2]}</dd>`).join('')}</dl><div class="row gap-6">${btn('open-device','详细参数','SlidersHorizontal',`data-id="${n.id}"`,'small')}${ibtn('delete-node','删除选中设备','Trash2',`data-id="${n.id}"`)}</div>`;}return `<h3>画布属性</h3><dl><dt>画布</dt><dd>${esc(activePage().name)}</dd><dt>介质</dt><dd>液态水</dd><dt>选择</dt><dd>${ui.selectedEdge?'已选连接 '+esc(ui.selectedEdge):'单击设备或连接'}</dd></dl>${ui.selectedEdge?btn('delete-edge','删除连接','Trash2',`data-id="${ui.selectedEdge}"`,'small'):btn('nav','管理模块','Boxes','data-route="modules"','small ghost')}`;}
function channelFor(m,v){return m.channels.find(c=>c.enabled&&(c.input===v.port||c.output===v.port));}
function renderEditor(){const m=mod();const contents={drawing:renderDrawing,attributes:renderAttributes,values:renderValues,models:renderEditorModels,code:renderCode,channels:renderChannels};return `<div class="editor-page"><header class="editor-header">${ibtn('nav','返回模块库','ChevronLeft','data-route="modules"')}<span class="object-icon">${icon(m.icon)}</span><div><h1>${esc(m.name)} <span class="muted mono" style="font-size:13px">${esc(m.code)}</span></h1><small>模块定义 · v${m.version} · ${m.ports.length} 端口 / ${m.channels.length} 通路</small></div><span class="push"></span>${badge(m.dirty?'有修改':'定义已载入',m.dirty?'warn':'')}${btn('compile-preview','检查与编译预览','CheckCheck')}${btn('save','保存定义','Save','','primary')}</header><nav class="tabs editor-tabs" aria-label="模块编辑页面">${EDITOR_TABS.map(([id,label,glyph])=>`<button data-action="editor-tab" data-value="${id}" class="${ui.moduleTab===id?'active':''}" aria-current="${ui.moduleTab===id?'page':'false'}">${icon(glyph)}${label}</button>`).join('')}</nav><section class="editor-content">${(contents[ui.moduleTab]||renderDrawing)()}</section><footer class="editor-footer"><span class="row gap-6">${icon('Box')}编辑模块定义</span><span class="optional">项目实例通过型号应用更新</span><span class="push"></span><span>代码仅编辑预览 · 运行使用示例数据</span></footer></div>`;}
function drawingSVG(m){const selected=ui.editorPort;const shape=m.drawing;return `<svg id="module-drawing" viewBox="0 0 720 430" role="group" aria-label="${esc(m.name)}图形与端口"><g class="draw-object${selected==='picture'?' selected':''}" data-draw-id="picture" tabindex="0" role="button" aria-label="设备图形"><rect x="${360-shape.width*3}" y="${215-shape.height*2}" width="${shape.width*6}" height="${shape.height*4}" rx="${shape.shape==='circle'?70:8}" fill="var(--surface)" stroke="var(--blue)" stroke-width="1.6"/><text x="360" y="215" fill="var(--text)" text-anchor="middle" font-size="18">${esc(shape.label)}</text><text x="360" y="239" fill="var(--muted)" text-anchor="middle" font-size="12">${esc(m.code)}</text></g>${m.channels.filter(c=>c.enabled).map(c=>{const a=m.ports.find(p=>p.id===c.input),b=m.ports.find(p=>p.id===c.output);return a&&b?`<path d="M ${a.x*7.2} ${a.y*4.3} H ${(a.x+b.x)*3.6} V ${b.y*4.3} H ${b.x*7.2}" fill="none" stroke="var(--orange)" stroke-width="1.2" stroke-dasharray="5 4" opacity=".7"/><text x="${(a.x*.82+b.x*.18)*7.2}" y="${a.y*4.3-15}" text-anchor="middle" fill="var(--accent)" font-size="11">${esc(c.name)}</text>`:'';}).join('')}${m.ports.map(p=>`<g class="draw-object${selected===p.id?' selected':''}" data-draw-id="${p.id}" tabindex="0" role="button" aria-label="端口 ${esc(p.name)}"><rect x="${p.x*7.2-16}" y="${p.y*4.3-16}" width="32" height="32" rx="5" fill="transparent" stroke="transparent"/><circle cx="${p.x*7.2}" cy="${p.y*4.3}" r="6" fill="${p.direction==='in'?`var(--${DOMAINS[p.domain].color})`:'var(--surface)'}" stroke="var(--${DOMAINS[p.domain].color})" stroke-width="1.7"/><text x="${p.x*7.2}" y="${p.y*4.3+27}" fill="var(--text)" font-size="12" text-anchor="middle">${esc(p.name)}</text><text x="${p.x*7.2}" y="${p.y*4.3+44}" fill="var(--muted)" font-size="11" text-anchor="middle">${esc(p.label)}</text></g>`).join('')}</svg>`;}
function renderDrawing(){const m=mod(),selected=m.ports.find(p=>p.id===ui.editorPort);return `<div class="editor-drawing"><div class="draw-left"><div class="draw-toolbar"><strong>图形与端口</strong><span class="muted">拖动布置 · 方向键微调</span><span class="push"></span>${btn('editor-tab','配置内部通路','Waypoints','data-value="channels"','small')}${ibtn('draw-center','居中图形','Scan')}</div><div class="draw-board" id="draw-board">${drawingSVG(m)}</div><div class="draw-toolbar"><span class="row gap-6"><span class="port-mark in"></span>入口</span><span class="row gap-6"><span class="port-mark"></span>出口</span><span class="push muted">虚线表示设备内部通路</span></div></div><aside class="draw-sidebar"><section><h3>添加绘制对象</h3><div class="draw-palette"><button data-action="select-picture">${icon('SquareDashed')}设备图形</button><button data-action="edit-drawing-label">${icon('Pencil')}图形名称</button>${Object.entries(DOMAINS).flatMap(([key,d])=>['in','out'].map(dir=>`<button data-action="add-port" data-domain="${key}" data-direction="${dir}"><span class="port-mark ${key} ${dir}"></span>${d.label}${dir==='in'?'输入':'输出'}</button>`)).join('')}</div><div class="notice"><span>${icon('Info')}</span><span>添加端口后，变量表会自动生成对应变量。</span></div></section><section><div class="spacer"></div><div class="row spread"><h3>对象属性</h3>${selected?ibtn('delete-port','删除选中端口','Trash2',`data-id="${selected.id}"`):''}</div><div class="stack" style="margin-top:14px">${selected?`<label class="field"><span>端口标识</span><input data-port-field="name" data-id="${selected.id}" value="${esc(selected.name)}" aria-label="端口标识"></label><label class="field"><span>中文说明</span><input data-port-field="label" data-id="${selected.id}" value="${esc(selected.label)}" aria-label="端口中文说明"></label><div class="row">${badge(DOMAINS[selected.domain].label,DOMAINS[selected.domain].color==='orange'?'warn':'blue')}${badge(selected.direction==='in'?'输入':'输出')}</div><div class="fields"><label class="field"><span>X / %</span><input type="number" min="5" max="95" data-port-field="x" data-id="${selected.id}" value="${selected.x}"></label><label class="field"><span>Y / %</span><input type="number" min="10" max="85" data-port-field="y" data-id="${selected.id}" value="${selected.y}"></label></div><small class="muted">通路：${esc(m.channels.find(c=>c.input===selected.id||c.output===selected.id)?.name||'未绑定')}</small>`:`<label class="field"><span>图形名称</span><input data-drawing-field="label" value="${esc(m.drawing.label)}" aria-label="图形名称"></label><label class="field"><span>图形形状</span><select data-drawing-field="shape">${option('rectangle','圆角矩形',m.drawing.shape)}${option('circle','椭圆',m.drawing.shape)}</select></label><div class="fields"><label class="field"><span>宽度</span><input type="number" min="15" max="60" data-drawing-field="width" value="${m.drawing.width}"></label><label class="field"><span>高度</span><input type="number" min="15" max="55" data-drawing-field="height" value="${m.drawing.height}"></label></div><small class="muted">选择端口查看编号、类型和通路。</small>`}</div></section></aside></div>`;}
function variableRows(m){return m.variables.filter(v=>(v.name+v.label+v.note).toLowerCase().includes(ui.variableSearch.toLowerCase())&&(!ui.onlyCommon||v.display)).map(v=>`<tr data-variable-row="${esc(v.id)}"><td><span class="mono">${esc(v.name)}</span><small>${esc(v.label)}</small></td><td>${v.type}</td><td>${esc(v.unit)}</td><td>${esc(m.ports.find(p=>p.id===v.port)?.name||'—')}<small>${esc(channelFor(m,v)?.name||'未绑定通路')}</small></td><td><input type="text" data-var-note="${esc(v.id)}" aria-label="${esc(v.name)} 备注" value="${esc(v.note)}" maxlength="120"></td><td><label class="check-label"><input type="checkbox" data-var-display="${esc(v.id)}" aria-label="常用变量 ${esc(v.name)}" ${v.display?'checked':''}>显示</label></td><td>${badge(v.origin==='parameter'?'参数':v.origin==='system'?'系统':v.writable?'输入':'输出',v.origin==='parameter'?'warn':'')}</td><td>${v.origin==='custom'?ibtn('delete-variable','删除变量 '+v.name,'Trash2',`data-id="${esc(v.id)}"`):'<span class="muted">—</span>'}</td></tr>`).join('');}
function renderAttributes(){const m=mod();return `<div class="editor-table-section"><div class="filterbar"><label class="search">${icon('Search')}<input data-filter="variableSearch" aria-label="搜索变量定义" value="${esc(ui.variableSearch)}" placeholder="变量名、中文名称或备注"></label><label class="check-label"><input type="checkbox" data-ui-toggle="onlyCommon" ${ui.onlyCommon?'checked':''}>仅常用变量</label><span class="push muted">${m.variables.length} 个变量</span>${btn('new-variable','新增变量','Plus','','primary')}</div><div class="panel table-wrap"><table class="variable-table"><thead><tr><th>变量 / 含义</th><th>类型</th><th>单位</th><th>端口 / 通路</th><th>备注</th><th>常用</th><th>属性</th><th></th></tr></thead><tbody id="variable-rows">${variableRows(m)}</tbody></table></div><section class="panel" style="margin-top:18px"><div class="panel-head"><h3>项目画布上的快捷控件</h3>${badge('由模块定义')}</div><div class="panel-body fields"><label class="field"><span>常用参数</span><select data-module-field="quickParam">${(PARAM_DEFS[m.kind]||[]).map(f=>option(f[0],f[1]+' · '+f[2],m.quickParam)).join('')||option('','暂无可调参数','')}</select></label><label class="field"><span>控件形式</span><select data-module-field="quickType">${[['slider','滑块与数值'],['switch','开关'],['number','数值输入'],['display','只读数显']].map(([k,v])=>option(k,v,m.quickType)).join('')}</select></label><div class="notice wide">${icon('Info')}<span>项目窗口优先呈现常用参数；修改模块定义后，通过型号应用更新项目实例。</span></div></div></section></div>`;}
function valueTable(m){const columns=ui.allBanks?[-1,0,1,2]:[-1,ui.bank];const vars=m.variables.filter(v=>(v.name+v.label).toLowerCase().includes(ui.valueSearch.toLowerCase()));return `<table class="value-table"><thead><tr><th>变量 / 单位</th>${columns.map(c=>`<th class="num">${c<0?'当前值':esc(m.bankNames[c])}<small style="display:block;font-weight:400">${c<0?'模块默认值':'库值 '+(c+1)}</small></th>`).join('')}</tr></thead><tbody>${vars.map(v=>`<tr><td><strong>${esc(v.label)}</strong><small><span class="mono">${esc(v.name)}</span> · ${esc(v.unit)}</small></td>${columns.map(c=>{const val=(c<0?m.values:m.banks[c])[v.id]??v.value;const diff=c>=0&&JSON.stringify(val)!==JSON.stringify(m.values[v.id]);return `<td class="num${diff?' edited':''}">${Array.isArray(val)?`<button class="array-btn" data-action="array-select" data-id="${esc(v.id)}" data-bank="${c<0?ui.bank:c}" aria-label="编辑 ${esc(v.name)} ${c<0?'当前值':'库值'+(c+1)}数组"${c<0?' disabled':''}>${val.map(n=>number(n,v.type.startsWith('int')?0:3)).join(', ')}</button>`:`<input type="number" step="${v.type==='int'?'1':'any'}" data-value-id="${esc(v.id)}" data-bank="${c}" aria-label="${esc(v.name)} ${c<0?'当前值':'库值'+(c+1)}" value="${typeof val==='number'?v.type==='int'?val:val.toFixed(m.precision):esc(val)}" ${c<0?'readonly':!v.writable?'disabled':''}>`}</td>`;}).join('')}</tr>`).join('')}</tbody></table>`;}
function bankDiff(m,index=ui.bank){return m.variables.filter(v=>v.writable&&JSON.stringify(m.values[v.id])!==JSON.stringify(m.banks[index][v.id]));}
function renderValues(){const m=mod(),array=m.variables.find(v=>v.id===ui.arrayVar&&v.type.endsWith('[8]'))||m.variables.find(v=>v.id==='system:form');const arr=m.banks[ui.bank][array.id];const form=m.banks[ui.bank]['system:form'],mix=m.banks[ui.bank]['system:mix'];return `<div class="value-layout"><section class="value-main"><div class="filterbar"><label class="search">${icon('Search')}<input data-filter="valueSearch" aria-label="查找变量值" value="${esc(ui.valueSearch)}" placeholder="查找参数或端口变量"></label><span class="push"></span><label class="check-label"><input type="checkbox" data-ui-toggle="allBanks" ${ui.allBanks?'checked':''}>三组对照</label></div><div class="row wrap spread" style="margin-bottom:14px"><div class="segmented">${[0,1,2].map(i=>`<button data-action="bank-select" data-value="${i}" class="${ui.bank===i?'active':''}">库值 ${i+1} · ${esc(m.bankNames[i])}</button>`).join('')}</div>${badge(bankDiff(m).length+' 项差异',bankDiff(m).length?'warn':'good')}</div><div class="panel table-wrap" id="value-table">${valueTable(m)}</div><div class="notice" style="margin-top:14px">${icon('Info')}<span>库值是独立的参数方案。保存保留草稿；点击“应用到当前值”后才改变模块当前值。</span></div></section><aside class="value-side"><section><h3>库值 ${ui.bank+1} · ${esc(m.bankNames[ui.bank])}</h3><label class="field"><span>方案名称</span><input data-bank-name="${ui.bank}" value="${esc(m.bankNames[ui.bank])}" maxlength="30" aria-label="库值方案名称"></label><div class="bank-direction"><span>库值 ${ui.bank+1}</span>${icon('ArrowRight')}<span>模块当前值</span></div><div class="stack" style="gap:8px">${btn('apply-bank','应用到当前值','ArrowRight','','primary')}${btn('capture-bank','当前值存入此库','Copy')}${btn('new-model','保存为设备型号','Database')}${btn('preview-design','预览设计函数 '+(ui.bank+1),'Braces','','ghost small')}</div><div class="spacer"></div><div class="row spread" style="margin:14px 0 10px"><h3>数组编辑</h3><span class="badge">库值 ${ui.bank+1}</span></div><label class="field"><select data-array-var aria-label="选择数组变量">${m.variables.filter(v=>v.type.endsWith('[8]')).map(v=>option(v.id,v.name,ui.arrayVar)).join('')}</select></label><div class="array-grid" style="margin-top:10px">${arr.map((v,i)=>`<label>[${i}]<input type="number" step="${array.type.startsWith('int')?'1':'any'}" data-array-index="${i}" data-id="${array.id}" aria-label="${array.name} 数组第 ${i+1} 项" value="${v}"></label>`).join('')}</div></section><section><div class="spacer"></div><h3 style="margin-top:14px">工质与质量比例</h3><div class="stack" style="gap:7px">${FLUIDS.map(([key,name,id])=>`<label class="check-label"><input type="checkbox" data-fluid-id="${id}" ${form.includes(id)?'checked':''}>${name}<small class="muted push">${id}</small></label>`).join('')}</div><div class="stack" style="gap:8px;margin-top:13px">${form.map((id,i)=>id?`<label class="mixture-row"><span>${esc(FLUIDS.find(f=>f[2]===id)?.[1]||id)}</span><input type="number" min="0" max="1" step=".01" data-mixture-index="${i}" aria-label="${esc(FLUIDS.find(f=>f[2]===id)?.[1]||id)}质量比例" value="${mix[i]}"><span></span></label>`:'').join('')}</div><div class="row spread" style="margin:14px 0"><span class="muted">合计 ${number(mix.reduce((a,b)=>a+Number(b),0),4)}</span>${btn('normalize-mixture','归一化','','','small')}</div><small class="muted">物性数据用于界面示例；此处不调用 REFPROP。</small></section></aside></div>`;}
function renderEditorModels(){const m=mod(),list=state.models.filter(v=>v.moduleId===m.id&&!v.archived);return `<div class="editor-table-section"><div class="section-title"><div><h2>${esc(m.name)}的设备型号</h2><p class="muted" style="font-size:12px;margin-top:6px">从库值保存型号，在项目中复用参数。</p></div>${btn('new-model','从库值保存型号','Plus','','primary')}</div><div class="panel table-wrap"><table><thead><tr><th>型号名称</th><th>版本</th><th>参数摘要</th><th>来源</th><th></th></tr></thead><tbody>${list.map(v=>`<tr><td><strong>${esc(v.name)}</strong><small>${esc(v.description)}</small></td><td>${badge('v'+v.version)}</td><td>${Object.entries(v.params).map(([k,val])=>`${esc((PARAM_DEFS[m.kind]||[]).find(f=>f[0]===k)?.[1]||k)} ${val}`).join(' · ')}</td><td>库值 ${v.bank}</td><td>${btn('select-model','查看型号','ArrowUpRight',`data-id="${v.id}"`,'small')}</td></tr>`).join('')||'<tr><td colspan="5">暂无型号，从一组库值保存开始。</td></tr>'}</tbody></table></div><div class="concept-flow"><div class="connection-node">编辑库值<small class="muted" style="display:block">参数方案</small></div>${icon('ArrowRight')}<div class="connection-node">保存命名型号<small class="muted" style="display:block">版本与来源</small></div>${icon('ArrowRight')}<div class="connection-node">应用到项目实例<small class="muted" style="display:block">预览差异后生效</small></div></div>${btn('nav','打开完整型号库','Database','data-route="models"','ghost')}</div>`;}
function renderCodePane(kind) {
  const m=mod(), source=kind==='design'?m.source.design[ui.designIndex]:m.source[kind];
  const title={runtime:'运行代码',header:'Header · 公共声明',design:'设计函数'}[kind];
  const name=kind==='runtime'?'Run.cpp':kind==='header'?'Header.h':`Design${ui.designIndex+1}.cpp`;
  return `<section class="module-code-pane" data-code-pane="${kind}" aria-labelledby="code-heading-${kind}">
    <header class="code-pane-head"><h3 id="code-heading-${kind}">${icon(kind==='design'?'Braces':'FileCode2')}${title}</h3><span class="mono code-file-name">${name}</span><span class="push"></span>${btn('check-code','检查结构','CheckCheck',`data-kind="${kind}" aria-label="检查${esc(title)}结构"`,'small')}${kind==='design'?btn('preview-design','调用预览','Play',`data-index="${ui.designIndex}"`,'small'):''}</header>
    ${kind==='design'?`<label class="code-design-picker">当前函数<select data-design-select aria-label="选择设计函数">${[0,1,2].map(i=>option(i,`设计函数 ${i+1} · ${m.bankNames[i]}`,ui.designIndex)).join('')}</select></label>`:''}
    <div class="code-editor"><div class="code-lines" aria-hidden="true">${source.split('\n').map((_,i)=>i+1).join('\n')}</div><textarea spellcheck="false" wrap="off" id="${kind==='runtime'?'module-code':'module-code-'+kind}" data-code-kind="${kind}"${kind==='design'?` data-design-index="${ui.designIndex}"`:''} aria-label="${esc(title)}编辑器">${esc(source)}</textarea></div>
  </section>`;
}
function renderCode() {
  const variables=mod().variables.filter(v=>v.origin==='parameter'||v.display);
  return `<div class="module-code-page">
    <div class="module-code-tools"><label>插入位置<select data-code-target aria-label="变量插入位置">${[['runtime','运行代码'],['header','Header'],['design','当前设计函数']].map(([key,label])=>option(key,label,ui.codeKind)).join('')}</select></label><label class="code-variable-picker">变量<select data-code-variable aria-label="选择插入变量" ${variables.length?'':'disabled'}>${variables.map(v=>option(v.name,`${v.name} · ${v.label}`,ui.codeVariable||variables[0]?.name)).join('')||option('','无可用变量','')}</select></label>${btn('insert-code-variable','插入到光标','Plus',variables.length?'':'disabled','small')}<span class="push muted">C / C++</span></div>
    <div class="module-code-grid">${renderCodePane('runtime')}${renderCodePane('header')}${renderCodePane('design')}</div>
    <div class="code-output" role="status" id="code-output"><strong>检查与调用输出</strong>\n${esc(ui.compileOutput)}</div>
  </div>`;
}
function renderChannels(){const m=mod();const first=m.channels[0],a=m.ports.find(p=>p.id===first?.input),b=m.ports.find(p=>p.id===first?.output);return `<div class="editor-table-section"><div class="section-title"><div><h2>定义设备内部通路</h2><p class="muted" style="font-size:12px;margin-top:6px">将同一物理通道的入口与出口关联；变量的通道列随绑定更新。</p></div>${btn('add-channel','新增通路','Plus','','primary')}</div><div class="panel table-wrap"><table class="channel-table"><thead><tr><th>通路名称</th><th>入口</th><th>出口</th><th>关系类型</th><th>启用</th><th></th></tr></thead><tbody>${m.channels.map(c=>`<tr><td><input class="cell-input" data-channel-id="${c.id}" data-channel-field="name" aria-label="${c.id} 通路名称" value="${esc(c.name)}"></td><td><select data-channel-id="${c.id}" data-channel-field="input" aria-label="${c.id} 入口">${option('','选择入口',c.input)}${m.ports.filter(p=>p.direction==='in').map(p=>option(p.id,p.name+' · '+p.label,c.input)).join('')}</select></td><td><select data-channel-id="${c.id}" data-channel-field="output" aria-label="${c.id} 出口">${option('','选择出口',c.output)}${m.ports.filter(p=>p.direction==='out').map(p=>option(p.id,p.name+' · '+p.label,c.output)).join('')}</select></td><td><select data-channel-id="${c.id}" data-channel-field="kind" aria-label="${c.id} 关系类型">${[['resistance','阻力关系'],['pressure','压差关系'],['flow','指定流量'],['signal','信号映射']].map(([k,v])=>option(k,v,c.kind)).join('')}</select></td><td><label class="check-label"><input type="checkbox" data-channel-id="${c.id}" data-channel-field="enabled" aria-label="启用 ${c.name}" ${c.enabled?'checked':''}>启用</label></td><td>${ibtn('delete-channel','删除 '+c.name,'Trash2',`data-id="${c.id}"`)}</td></tr>`).join('')||'<tr><td colspan="6">此模块尚未设置内部通路。</td></tr>'}</tbody></table></div><div class="row spread" style="margin:14px 0 20px"><small class="muted">类型相同的端口才能组成通路；每个端口只绑定一条启用通路。</small>${btn('check-channels','检查通路','ListChecks','','small')}</div><div id="channel-feedback"></div><div class="channel-diagram"><div class="stack" style="gap:5px;text-align:center"><span class="mono">${a?esc(a.name):'入口'}</span><small class="muted">${a?esc(a.label):'选择端口'}</small></div><span class="channel-link"></span><div class="channel-box"><strong>${esc(m.name)}</strong><small class="muted" style="display:block;margin-top:4px">${first?esc(first.name):'内部关系'}</small></div><span class="channel-link"></span><div class="stack" style="gap:5px;text-align:center"><span class="mono">${b?esc(b.name):'出口'}</span><small class="muted">${b?esc(b.label):'选择端口'}</small></div></div></div>`;}
function renderNodesPage(){const domain=DOMAINS[ui.nodeDomain];return `<div class="page-shell">${heading('节点与端口定义','按物理类型组织接口，明确变量含义与连接规则。',btn('nav','返回模块库','ChevronLeft','data-route="modules"'))}<div class="split-view"><aside class="side-nav"><div class="side-caption">接口领域</div>${Object.entries(DOMAINS).map(([k,d])=>`<button data-action="node-domain" data-value="${k}" class="${k===ui.nodeDomain?'active':''}">${icon(d.icon)}${d.label}端口</button>`).join('')}</aside><div class="stack"><section class="panel"><div class="panel-head"><div class="row"><span class="object-icon">${icon(domain.icon)}</span><div><h2>${domain.label}端口</h2><small class="muted">${ui.nodeDomain==='fluid'?'状态量、流量与工质组成':'接口与变量定义示例'}</small></div></div>${badge(ui.nodeDomain==='fluid'?'液态水场景':'接口预留',ui.nodeDomain==='fluid'?'good':'warn')}</div><div class="table-wrap"><table><thead><tr><th>变量后缀</th><th>中文名称</th><th>单位</th><th>说明</th></tr></thead><tbody>${(ui.nodeDomain==='fluid'?[['FLOW','质量流量','kg/s','沿端口约定方向记录，可表达反向流动'],['PRE','绝对压力','MPa','与求解器约定之间显式换算'],['ENTHALPY','比焓','kJ/kg','能量输运状态量'],['TEMP','温度','°C','工程显示单位'],['VOLUME','密度','kg/m³','参考命名对应密度，不能当作比容'],['Q','干度','—','相态描述；当前水网范围不扩展两相求解'],['X','质量组分','—','与 FORM 工质顺序对应']]:ui.nodeDomain==='info'?[['VALUE','信号数值','自定义','根据物理量定义单位'],['QUALITY','数据质量','—','有效、过期或缺失状态']]:ui.nodeDomain==='power'?[['VOLTAGE','电压','V','电气接口的定义示例'],['CURRENT','电流','A','当前原型不提供电网计算']]:[['SPEED','转速','r/min','机械接口的定义示例'],['TORQUE','转矩','N·m','当前原型不提供机械求解']]).map(row=>`<tr>${row.map((v,i)=>`<td${i===0?' class="mono"':''}>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h3>连接规则</h3></div><div class="panel-body stack"><div class="row">${icon('CheckCircle2')}同一内部通路的两端类型一致</div><div class="row">${icon('CheckCircle2')}端口拥有稳定标识，显示名称可以独立编辑</div><div class="row">${icon('CheckCircle2')}一个项目端口对应一条连接，分支使用连接节点</div><div class="row">${icon('CheckCircle2')}类型与单位定义供变量表、图形、型号和曲线共用</div></div></section>${btn('edit-module','在模块中配置端口','ArrowRight',`data-id="${ui.nodeDomain==='fluid'?'valve':'pid'}"`,'primary')}</div></div></div>`;}
function renderModels(){let models=state.models.filter(m=>(ui.modelFilter==='archived'?m.archived:!m.archived)&&(m.name+mod(m.moduleId).name).toLowerCase().includes(ui.modelSearch.toLowerCase()));const selected=models.find(m=>m.id===state.selectedModel)||models[0];return `<div class="page-shell">${heading('设备型号库','从已验证的参数形成型号；项目实例保留自己的参数与来源版本。',btn('new-model','保存新型号','Plus','','primary'))}<div class="filterbar"><label class="search">${icon('Search')}<input data-filter="modelSearch" aria-label="搜索型号" placeholder="型号名称或模块名称" value="${esc(ui.modelSearch)}"></label><div class="segmented">${[['all','在用型号'],['archived','已归档']].map(([k,v])=>`<button data-action="model-filter" data-value="${k}" class="${ui.modelFilter===k?'active':''}">${v}</button>`).join('')}</div><span class="push muted">${models.length} 个型号</span>${btn('export','导出型号库','Download','data-format="models"','small')}</div><div class="model-layout"><section class="panel"><div class="table-wrap"><table><thead><tr><th>型号名称</th><th>所属模块</th><th>版本</th><th>主要参数</th><th></th></tr></thead><tbody>${models.map(m=>`<tr class="${m.id===selected?.id?'model-selected':''}"><td><button data-action="focus-model" data-id="${m.id}" style="text-align:left;padding:0"><strong>${esc(m.name)}</strong><small>${esc(m.description)}</small></button></td><td>${esc(mod(m.moduleId).name)}</td><td>${badge('v'+m.version)}</td><td>${Object.entries(m.params).slice(0,2).map(([k,v])=>`<span class="mono">${v}</span> ${(PARAM_DEFS[mod(m.moduleId).kind]||[]).find(f=>f[0]===k)?.[2]||''}`).join(' · ')}</td><td>${ibtn('focus-model','查看型号 '+m.name,'ChevronRight',`data-id="${m.id}"`)}</td></tr>`).join('')||'<tr><td colspan="5">没有匹配的型号。</td></tr>'}</tbody></table></div></section>${selected?`<aside class="model-detail stack"><section class="panel"><div class="panel-head"><div><h2>${esc(selected.name)}</h2><small class="muted">${esc(mod(selected.moduleId).name)} · v${selected.version}</small></div>${icon('Database')}</div><div class="panel-body stack"><p class="muted" style="font-size:12px">${esc(selected.description)}</p><div class="fields">${Object.entries(selected.params).map(([key,val])=>{const f=(PARAM_DEFS[mod(selected.moduleId).kind]||[]).find(f=>f[0]===key);return `<div class="field"><span>${esc(f?.[1]||key)}</span><strong>${number(val,f?.[0]==='opening'?0:2)} <small class="muted">${f?.[2]||''}</small></strong></div>`;}).join('')}</div><div class="spacer"></div>${btn('insert-model','插入当前项目','Plus',`data-id="${selected.id}"`,'primary')}${btn('apply-model-to-instance','应用到已有设备','GitCompareArrows',`data-id="${selected.id}"`)}<div class="row">${btn('edit-model','保存新版本','Pencil',`data-id="${selected.id}"`,'small')}${btn('archive-model',selected.archived?'恢复型号':'归档型号','History',`data-id="${selected.id}"`,'ghost small')}</div><small class="muted">更新型号不会自动改动已插入的实例。</small></div></section><section class="panel"><div class="panel-head"><h3>版本记录</h3>${badge(selected.versions.length+' 个版本')}</div><div class="panel-body">${selected.versions.slice().reverse().map(v=>`<div class="version-item"><span class="object-icon" style="width:26px;height:26px">${icon('History')}</span><div class="grow"><strong>v${v.version}</strong><small>${esc(v.note)}</small></div>${v.version===selected.version?badge('当前'):btn('model-version','对照','','data-version="'+v.version+'" data-id="'+selected.id+'"','small')}</div>`).join('')}</div></section></aside>`:''}</div></div>`;}
function renderBench(){const b=state.bench,m=mod(b.moduleId),run=b.run;return `<div class="page-shell">${heading('独立验证台','用独立边界与参数检查设备；测试不会改变项目实例。',btn('edit-module','编辑模块','Pencil',`data-id="${m.id}"`)+btn('save','保存测试配置','Save'))}<div class="bench-layout"><aside class="stack"><section class="panel"><div class="panel-head"><h3>被测设备</h3>${badge('单机测试','blue')}</div><div class="panel-body stack"><label class="field"><span>模块</span><select data-bench-module aria-label="选择被测模块" ${['running','paused'].includes(run.status)?'disabled':''}>${state.modules.map(x=>option(x.id,x.name,x.id===m.id?x.id:m.id)).join('')}</select></label>${(PARAM_DEFS[m.kind]||[]).map(f=>`<label class="field"><span>${f[1]}</span><div class="field-unit"><input type="number" data-bench-param="${f[0]}" min="${f[3]}" max="${f[4]}" step="${f[5]}" value="${b.params[f[0]]??f[6]}" ${run.status==='running'?'disabled':''}><span>${f[2]}</span></div></label>`).join('')}<small class="muted">参数仅用于此测试副本。</small></div></section><section class="panel"><div class="panel-head"><h3>边界条件</h3></div><div class="panel-body stack">${[['inlet','入口压力','kPa'],['outlet','出口压力','kPa'],['temperature','入口温度','°C']].map(([key,label,unit])=>`<label class="field"><span>${label}</span><div class="field-unit"><input type="number" data-bench-boundary="${key}" step="any" value="${b.boundary[key]}" aria-label="测试${label}" ${run.status==='running'?'disabled':''}><span>${unit}</span></div></label>`).join('')}<label class="field"><span>时间步长</span><div class="field-unit"><input type="number" data-bench-step ${run.status==='running'?'disabled':''} value="${run.step}" min=".01" max="10" step=".01"><span>s</span></div></label></div></section></aside><section class="panel"><div class="run-control"><div class="runtime"><span class="dot" style="color:var(--green)"></span><strong>${m.name} · ${statusText(run)}</strong><span class="mono" data-bench-time>${clockLabel(run.time)}</span></div><span class="push"></span>${runControls('bench',run)}</div><div class="bench-schematic"><svg viewBox="0 0 780 180" role="img" aria-label="独立边界与被测设备"><path d="M 145 80 H 620" class="net-line"/><circle cx="145" cy="80" r="25" fill="var(--blue-soft)" stroke="var(--blue)"/><circle cx="620" cy="80" r="25" fill="var(--blue-soft)" stroke="var(--blue)"/><rect x="300" y="48" width="165" height="65" rx="7" fill="var(--surface)" stroke="var(--orange)"/><text x="382" y="84" text-anchor="middle" fill="var(--text)" font-size="15">${esc(m.name)}</text><text x="145" y="85" text-anchor="middle" fill="var(--blue)" font-size="14">P</text><text x="620" y="85" text-anchor="middle" fill="var(--blue)" font-size="14">P</text><text x="145" y="136" text-anchor="middle" fill="var(--muted)" font-size="12">${b.boundary.inlet} kPa</text><text x="620" y="136" text-anchor="middle" fill="var(--muted)" font-size="12">${b.boundary.outlet} kPa</text><text x="382" y="150" text-anchor="middle" fill="var(--muted)" font-size="11">独立测试副本 · 示例响应</text></svg></div><div class="tabs">${[['results','运行结果'],['curves','趋势曲线'],['events','事件记录']].map(([k,v])=>`<button data-action="bench-tab" data-value="${k}" class="${ui.benchTab===k?'active':''}">${v}</button>`).join('')}</div><div id="bench-results">${benchResults()}</div></section></div></div>`;}
function runControls(scope,run){return `${btn(scope==='bench'?'run-bench':'run-project',run.status==='paused'?'继续':'运行','Play',`data-command="run" ${run.status==='running'?'disabled':''}`,'run small')}${btn(scope==='bench'?'run-bench':'run-project','暂停','Pause',`data-command="pause" ${run.status==='running'?'':'disabled'}`,'small')}${btn(scope==='bench'?'run-bench':'run-project','单步','StepForward',`data-command="step" ${run.status==='running'?'disabled':''}`,'small')}${btn(scope==='bench'?'run-bench':'run-project','停止','Square',`data-command="stop" ${['ready','stopped'].includes(run.status)?'disabled':''}`,'small')}`;}
function benchResults(){const run=state.bench.run,v=run.values;if(ui.benchTab==='events')return `<div class="panel-body"><div class="notice">${icon('Info')}事件对应独立测试；所有数值为交互演示。</div><div class="log-list">${run.events.slice().reverse().map(e=>`<div class="log-line"><time>${number(e.t,1)} s</time><span>${esc(e.text)}</span></div>`).join('')||empty('还没有测试事件','设置边界后运行或单步。')}</div></div>`;return `<div class="metric-row"><div class="metric"><span>质量流量</span><strong data-bench-q>${number(v.q,3)}</strong><small>kg/s</small></div><div class="metric"><span>出口压力</span><strong>${number(v.pressure||state.bench.boundary.outlet,2)}</strong><small>kPa</small></div><div class="metric"><span>温度</span><strong>${number(v.temperature,1)}</strong><small>°C</small></div></div><div class="chart-panel"><div class="chart-heading"><h3>单机响应曲线</h3><span class="push"></span>${badge('示例数据')}</div>${chartSvg(run.history,['q'],'bench-chart')}${!run.history.length?'<p class="muted" style="font-size:12px;text-align:center">运行或单步后生成示例响应曲线</p>':''}<div class="chart-readout" id="bench-chart-readout">${clockLabel(run.time)} · ${mod(state.bench.moduleId).name}</div></div>${ui.benchTab==='results'?`<div class="table-wrap"><table><thead><tr><th>观察量</th><th class="num">当前值</th><th>单位</th><th>数据来源</th></tr></thead><tbody><tr><td>出口质量流量</td><td class="num">${number(v.q,4)}</td><td>kg/s</td><td>独立测试示例</td></tr><tr><td>压力差</td><td class="num">${number(state.bench.boundary.inlet-state.bench.boundary.outlet,3)}</td><td>kPa</td><td>输入边界差</td></tr></tbody></table></div>`:''}<div class="panel-body row spread"><small class="muted">单机测试与主系统运行互相独立。</small>${btn('record-bench','保存测试记录','Save','','small')}</div>`;}
function currentChartRun(){if(state.charts.source==='live')return project().run;return state.records.find(r=>r.id===state.charts.source)||project().run;}
function renderCurves(){const run=currentChartRun(),history=run.history;return `<div class="page-shell">${heading('曲线与工况对照','从设备变量加入曲线，跟随运行、暂停和单步观察变化。',btn('add-chart-variable','添加观察变量','Plus','','primary')+btn('export','导出曲线','Download','data-format="csv"'))}<div class="filterbar"><label class="field" style="flex-direction:row;align-items:center"><span>数据来源</span><select data-chart-source aria-label="曲线数据来源">${option('live','当前主系统 · '+project().name,state.charts.source)}${state.records.filter(r=>r.history.length).map(r=>option(r.id,r.name+' · 示例记录',state.charts.source)).join('')}</select></label><label class="check-label"><input type="checkbox" data-chart-compare ${state.charts.compare?'checked':''}>叠加额定工况基准</label><span class="push"></span>${state.charts.source==='live'?runControls('project',project().run):badge('历史记录','blue')}</div><div class="chart-grid-layout"><section class="panel"><div class="chart-panel"><div class="chart-heading"><h2>管网流量</h2><span class="muted">${esc(state.charts.source==='live'?project().name:run.projectName)}</span><span class="push"></span><div class="chart-legend">${['q','a','b'].map(k=>`<button data-action="toggle-series" data-value="${k}" class="${state.charts.series[k]?'':'off'}" aria-pressed="${state.charts.series[k]}"><span class="series-key ${SERIES[k].color}"></span>${SERIES[k].short}</button>`).join('')}${state.charts.compare?'<span class="muted">┄ 额定基准</span>':''}</div></div><div id="main-chart">${chartSvg(history,['q','a','b'],'main-flow-chart',state.charts.compare)}</div><div class="chart-readout" id="main-flow-chart-readout">${history.length?`${clockLabel(history.at(-1).t)} · 主管 ${number(history.at(-1).q,3)} kg/s`:'还没有当前运行数据。可以运行、单步，或切换到示例历史记录。'}</div></div><div class="chart-variable-list"><span class="badge">P1 · 出口流量</span><span class="badge">V1 · 出口流量</span><span class="badge">V2 · 出口流量</span>${state.charts.extra.filter(v=>v.projectId===(state.charts.source==='live'?project().id:run.projectId)).map(v=>`<span class="badge blue">${esc(v.label)}<button data-action="remove-chart-var" data-id="${esc(v.id)}" aria-label="移除 ${esc(v.label)}">${icon('X')}</button></span>`).join('')}</div></section><section class="panel"><div class="chart-panel"><div class="chart-heading"><h3>出口压力</h3><span class="push muted">P1 · kPa</span></div><div id="pressure-chart">${chartSvg(history,['pressure'],'pressure-line')}</div><div class="chart-readout" id="pressure-line-readout">${badge('示例数据')}</div></div></section><section class="panel"><div class="chart-panel"><div class="chart-heading"><h3>出口温度</h3><span class="push muted">P1 · °C</span></div><div id="temperature-chart">${chartSvg(history,['temperature'],'temperature-line')}</div><div class="chart-readout" id="temperature-line-readout">${badge('示例数据')}</div></div></section></div><div id="extra-charts" class="chart-grid-layout" style="margin-top:18px">${extraChartsMarkup()}</div>${run.events?.length?`<section class="panel" style="margin-top:18px"><div class="panel-head"><h3>本次运行事件</h3></div><div class="log-list">${run.events.slice(-5).map(e=>`<div class="log-line"><time>${number(e.t,1)} s</time><span>${esc(e.text)}</span></div>`).join('')}</div></section>`:''}</div>`;}
function renderRuns(){let list=state.records.filter(r=>ui.runFilter==='all'||r.status===ui.runFilter);const selected=list.find(r=>r.id===ui.selectedRecord)||list[0];return `<div class="page-shell">${heading('运行记录','每次记录保留项目来源、参数快照与曲线，方便重复查看和对照。',btn('record-project','记录当前运行','Save')+btn('export','导出结果','Download','data-format="report"'))}<div class="filterbar"><div class="segmented">${[['all','全部记录'],['completed','已完成'],['failed','失败记录']].map(([k,v])=>`<button data-action="run-filter" data-value="${k}" class="${ui.runFilter===k?'active':''}">${v}</button>`).join('')}</div><span class="push muted">${list.length} 条记录</span></div><div class="model-layout"><section class="panel table-wrap"><table><thead><tr><th>记录名称 / 来源</th><th>模式</th><th>仿真时间</th><th>状态</th><th></th></tr></thead><tbody>${list.map(r=>`<tr class="${r.id===selected?.id?'model-selected':''}"><td><button data-action="select-record" data-id="${r.id}" style="text-align:left;padding:0"><strong>${esc(r.name)}</strong><small>${esc(r.projectName)} · ${r.id}</small></button></td><td>${r.mode}</td><td class="mono">${number(r.time,1)} s</td><td>${badge(r.status==='failed'?'检查失败':statusText(r),r.status==='failed'?'error':'good')}</td><td>${ibtn('select-record','查看运行记录','ChevronRight',`data-id="${r.id}"`)}</td></tr>`).join('')||'<tr><td colspan="5">暂无此状态的记录。</td></tr>'}</tbody></table></section>${selected?`<aside class="panel"><div class="panel-head"><h2>记录详情</h2>${badge('示例记录','warn')}</div><div class="run-details"><dl><dt>记录</dt><dd>${esc(selected.name)}</dd><dt>项目</dt><dd>${esc(selected.projectName)}</dd><dt>运行标识</dt><dd class="mono">${selected.id}</dd><dt>仿真时间</dt><dd>${number(selected.time,1)} s</dd><dt>记录点数</dt><dd>${selected.history.length}</dd><dt>状态</dt><dd>${selected.status==='failed'?'边界未完整':statusText(selected)}</dd></dl><div class="spacer" style="margin:20px 0"></div><h3 style="margin-bottom:10px">参数快照</h3>${Object.keys(selected.params).length?`<div class="code-preview">${esc(JSON.stringify(selected.params,null,2))}</div>`:'<p class="muted">检查失败，尚未生成计算结果。</p>'}${selected.status==='failed'?`<div class="notice error" style="margin-top:15px">${icon('Info')}示例诊断：二次侧缺少完整边界条件。</div>`:''}<div class="stack" style="margin-top:18px">${btn('record-curves','查看该次曲线','Activity',`data-id="${selected.id}" ${selected.history.length?'':'disabled'}`,'primary')}${btn('export','导出记录 JSON','FileJson',`data-format="record" data-id="${selected.id}"`)}${selected.projectId?btn('open-project','打开来源项目','ArrowUpRight',`data-id="${selected.projectId}"`,'ghost'):''}</div></div></aside>`:''}</div></div>`;}
function renderControls(){const p=project();return `<div class="page-shell">${heading('项目控制逻辑','组织输入、控制代码与输出变量，预览每一步的动作。',btn('control-template','载入示例','FileCode2')+btn('preview-control','预览一个周期','StepForward','','primary')+btn('save','保存脚本','Save'))}<div class="connection-layout"><aside class="stack"><section class="panel"><div class="panel-head"><h3>控制程序</h3>${badge('Lua')}</div><div class="panel-body stack"><label class="field"><span>名称</span><input value="${esc(p.controlConfig.name)}" aria-label="控制程序名称" data-control-name></label><label class="field"><span>执行时机</span><select data-control-setting="when">${option("accepted","每个接受步之后",p.controlConfig.when)}${option("manual","手动触发",p.controlConfig.when)}</select></label><label class="field"><span>控制周期</span><div class="field-unit"><input type="number" value="${p.controlConfig.period}" min="10" step="10" data-control-setting="period" aria-label="控制周期"><span>ms</span></div></label></div></section><section class="panel"><div class="panel-head"><h3>观察与输出变量</h3></div><div class="panel-body stack"><div><span class="muted">输入</span><div class="code-preview" style="padding:9px;margin-top:5px">${esc(p.controlConfig.input||"未配置")}</div></div><div><span class="muted">输出</span><div class="code-preview" style="padding:9px;margin-top:5px">${esc(p.controlConfig.output||"未配置")}</div></div>${btn('choose-control-vars','选择变量','Plus','','small')}</div></section><div class="notice">${icon('Info')}<span>本页演示控制配置与执行反馈；不会运行 Lua 或发送外部控制。</span></div></aside><div class="panel"><div class="code-toolbar">${icon('FileCode2')}<span class="mono">${esc(p.id)} / control.lua</span><span class="push"></span>${badge('编辑预览','warn')}</div><div class="code-editor" style="height:365px;min-height:300px"><div class="code-lines" aria-hidden="true">${p.control.split('\n').map((_,i)=>i+1).join('\n')}</div><textarea id="control-code" data-control-code spellcheck="false" aria-label="项目控制脚本" wrap="off">${esc(p.control)}</textarea></div><div class="code-output" id="control-output" role="status"><strong>周期预览</strong>\n${esc(ui.controlOutput)}</div><div class="panel-body"><h3>一次控制周期</h3><div class="concept-flow"><div class="connection-node">读取输入</div>${icon('ArrowRight')}<div class="connection-node">形成参数命令</div>${icon('ArrowRight')}<div class="connection-node">确认生效时刻</div></div></div></div></div></div>`;}
function projectVariables(){return project().pages.flatMap(p=>p.nodes).flatMap(n=>{const m=moduleOf(n);const params=paramDefs(n).map(f=>({id:n.id+'.'+f[0].toUpperCase(),nodeId:n.id,name:f[1],device:n.name,unit:f[2],value:n.params[f[0]],writable:true}));const out=[{id:n.id+'.OUT_FLOW',nodeId:n.id,name:'出口质量流量',device:n.name,unit:'kg/s',value:flowFor(n),writable:false},{id:n.id+'.OUT_PRE',nodeId:n.id,name:'出口压力',device:n.name,unit:'kPa',value:project().run.values.pressure||120,writable:false},{id:n.id+'.OUT_TEMP',nodeId:n.id,name:'出口温度',device:n.name,unit:'°C',value:project().run.values.temperature,writable:false}];return params.concat(out);});}
function connectionVariableRows(){return projectVariables().filter(v=>(v.id+v.name+v.device).toLowerCase().includes(ui.connectionSearch.toLowerCase())).map(v=>`<tr><td><span class="mono">${v.id}</span><small>${esc(v.device)} · ${v.name}</small></td><td class="num mono">${number(v.value,3)}</td><td>${v.unit}</td><td>${badge(v.writable?'可设置':'只读',v.writable?'warn':'')}</td><td>${badge('示例','blue')}</td><td><div class="row gap-6">${ibtn('copy-var','复制变量标识','Copy',`data-value="${v.id}"`)}${ibtn('add-specific-curve','加入曲线','Activity',`data-id="${v.id}" data-label="${esc(v.device+' · '+v.name)}"`)}</div></td></tr>`).join('');}
function renderConnections(){return `<div class="page-shell">${heading('数据与外部对接','统一查找变量，配置接口、串口与消息观察。',badge('连接与收发均为演示','warn')+btn('save','保存对接配置','Save'))}<section class="panel"><nav class="tabs" aria-label="数据对接页面">${[['variables','变量浏览','Table2'],['api','接口调用','Braces'],['serial','串口配置','Plug'],['bindings','变量绑定','Cable'],['messages','消息中心','MessageSquare']].map(([k,v,i])=>`<button data-action="connection-tab" data-value="${k}" class="${ui.connectionTab===k?'active':''}">${icon(i)}${v}</button>`).join('')}</nav><div class="panel-body">${connectionContent()}</div></section></div>`;}
function connectionContent(){
  if(ui.connectionTab==='variables')return `<div class="filterbar"><label class="search">${icon('Search')}<input data-filter="connectionSearch" aria-label="搜索对接变量" placeholder="设备、变量名或标识" value="${esc(ui.connectionSearch)}"></label><span class="muted">${esc(project().name)}</span><span class="push"></span>${btn('export','导出变量表','Download','data-format="variables"','small')}</div><div class="table-wrap"><table><thead><tr><th>变量标识 / 名称</th><th class="num">当前值</th><th>单位</th><th>读写属性</th><th>数据来源</th><th></th></tr></thead><tbody id="connection-variable-rows">${connectionVariableRows()}</tbody></table></div>`;
  if(ui.connectionTab==='api')return `<div class="connection-layout"><aside class="stack"><h3>调用场景</h3><div class="side-nav"><button class="active" data-action="api-example" data-value="read">${icon('ArrowDownToLine')}读取变量</button><button data-action="api-example" data-value="set">${icon('Pencil')}提交参数命令</button><button data-action="api-example" data-value="status">${icon('Activity')}查询运行状态</button></div><label class="field"><span>示例目标</span><input value="本地演示接口" readonly></label><div class="notice">${icon('Info')}此页面展示请求与回执，不发起网络请求。</div></aside><div class="stack"><div class="row"><span class="badge blue">GET</span><strong class="mono" id="api-path">/variables/V1.OPENING</strong><span class="push"></span>${btn('api-preview','预览请求','Play','','primary')}</div><div class="code-preview" id="api-request">{
  "project_id": "${project().id}",
  "variable": "V1.OPENING"
}</div><div class="section-title" style="margin:8px 0 0"><h3>响应预览</h3>${badge('示例数据')}</div><div class="code-preview" id="api-response">点击“预览请求”查看示例回执。</div><div class="notice"><span>${icon('CheckCircle2')}</span><span>参数命令的回执区分“已接收、已应用、已拒绝”，并显示命令标识与生效仿真时间。</span></div></div></div>`;
  if(ui.connectionTab==='serial'){const c=state.connectors.find(c=>c.id===ui.selectedConnector&&c.kind==='serial')||state.connectors.find(c=>c.kind==='serial');return `<div class="connection-layout"><aside class="stack"><div class="row spread"><h3>串口连接</h3>${ibtn('add-connector','添加串口连接','Plus')}</div><div class="side-nav">${state.connectors.filter(c=>c.kind==='serial').map(c=>`<button data-action="select-connector" data-id="${c.id}" class="${c.id===ui.selectedConnector?'active':''}">${icon('Plug')}<span>${esc(c.name)}<small class="muted" style="display:block">${c.port} · ${c.baud}</small></span></button>`).join('')}</div><div class="notice">${icon('Info')}串口打开和收发仅模拟状态，不访问硬件。</div></aside><div class="stack"><div class="row spread"><div><h3>${esc(c.name)}</h3><small class="muted">保存后保留连接参数</small></div>${badge(c.connected?'演示已连接':'未连接',c.connected?'good':'')}</div><div class="fields"><label class="field"><span>端口</span><select data-connector-id="${c.id}" data-connector-field="port">${['COM1','COM3','COM5'].map(x=>option(x,x,c.port)).join('')}</select></label><label class="field"><span>波特率</span><select data-connector-id="${c.id}" data-connector-field="baud">${['9600','19200','57600','115200'].map(x=>option(x,x,c.baud)).join('')}</select></label><label class="field"><span>数据位</span><select data-connector-id="${c.id}" data-connector-field="bits">${option('8','8',c.bits||'8')}${option('7','7',c.bits||'8')}</select></label><label class="field"><span>校验位</span><select data-connector-id="${c.id}" data-connector-field="parity">${['None','Even','Odd'].map(x=>option(x,x,c.parity||'None')).join('')}</select></label></div><div class="row">${btn('connect-demo',c.connected?'断开演示':'连接演示','Plug',`data-id="${c.id}"`,'primary')}<small class="muted">${c.connected?'可以模拟一条消息收发':'尚未启动模拟连接'}</small></div><div class="spacer"></div><h3>发送消息</h3><div class="row"><input id="serial-message" aria-label="串口模拟发送消息" value="#Get/V1.OPENING" style="flex:1">${btn('serial-send','模拟发送','ArrowUpRight',`data-id="${c.id}" ${c.connected?'':'disabled'}`)}</div><div class="code-output" id="serial-output" role="status">等待模拟消息。</div></div></div>`;}
  if(ui.connectionTab==='bindings')return `<div class="stack"><div class="row spread"><div><h3>输入输出映射</h3><p class="muted" style="font-size:12px;margin-top:4px">给外部字段指定变量、方向与单位。</p></div>${btn('add-binding','添加映射','Plus','','primary')}</div><div class="table-wrap"><table><thead><tr><th>外部字段</th><th>项目变量</th><th>方向</th><th>单位</th><th>状态</th></tr></thead><tbody id="binding-rows">${bindingsForProject().map((b,i)=>`<tr><td class="mono">${esc(b.external)}</td><td><select data-binding-index="${i}" aria-label="映射 ${i+1} 的变量">${projectVariables().filter(v=>b.direction!=='write'||v.writable).map(v=>option(v.id,v.id+' · '+v.name,b.variable)).join('')}</select></td><td>${badge(b.direction==='write'?'外部 → 项目':'项目 → 外部',b.direction==='write'?'warn':'blue')}</td><td>${esc(b.unit)}</td><td>${badge('未连接')}</td></tr>`).join('')}</tbody></table></div><div class="notice">${icon('Info')}外部写入目标的类型、范围和单位需与变量定义一致；此处仅保存映射配置。</div></div>`;
  return `<div class="stack"><div class="row spread"><h3>消息与事件</h3><div class="row">${badge(state.messages.length+' 条记录')}${btn('demo-message','生成示例消息','Plus','','small')}${btn('export','导出消息','Download','data-format="messages"','small')}</div></div><div class="log-list" style="max-height:560px">${state.messages.map(m=>`<div class="log-line"><time>${esc(m.time)}</time><span class="log-kind">${esc(m.kind)}</span><span>${esc(m.text)}</span></div>`).join('')}</div></div>`;
}
function renderSettings(){return `<div class="page-shell">${heading('项目与工作台设置','配置项目、介质、求解参数与界面偏好。',btn('save','保存设置','Save','','primary'))}<div class="settings-layout"><aside class="side-nav">${[['project','项目属性','Folder'],['medium','介质与单位','Droplets'],['solver','运行与求解','SlidersHorizontal'],['appearance','界面与布局','Monitor'],['storage','保存与交换','Database']].map(([k,l,i])=>`<button data-action="settings-tab" data-value="${k}" class="${ui.settingsTab===k?'active':''}">${icon(i)}${l}</button>`).join('')}</aside><section class="panel">${settingsContent()}</section></div></div>`;}
function settingsContent(){const p=project();
  if(ui.settingsTab==='project')return `<div class="settings-section"><h3>项目属性</h3><p>名称和说明用于项目列表、运行记录与导出文件。</p><div class="fields"><label class="field"><span>项目名称</span><input data-project-field="name" value="${esc(p.name)}" maxlength="50" aria-label="项目名称"></label><label class="field"><span>项目标识</span><input value="${p.id}" readonly></label><label class="field wide"><span>项目说明</span><textarea data-project-field="description" aria-label="项目说明" maxlength="240">${esc(p.description)}</textarea></label></div></div><div class="settings-section"><div class="row spread"><h3>画布</h3>${btn('new-canvas','添加画布','Plus','','small')}</div>${p.pages.map(pg=>`<div class="list-row" style="padding:12px 0">${icon('Layers')}<div class="grow"><strong>${esc(pg.name)}</strong><small>${pg.nodes.length} 个设备 · ${pg.edges.length} 条连接</small></div>${btn('rename-canvas','重命名','Pencil',`data-id="${pg.id}"`,'small ghost')}</div>`).join('')}</div>`;
  if(ui.settingsTab==='medium')return `<div class="settings-section"><h3>介质配置</h3><p>当前真实求解目标保持液态水；其他工质先用于接口页面设计。</p><div class="fields"><label class="field"><span>默认介质</span><select data-project-field="medium">${option('water','纯液态水',p.medium)}</select></label><label class="field"><span>显示单位方案</span><input value="工程单位 · 本轮原型" readonly></label></div><div class="notice" style="margin-top:20px">${icon('Droplets')}换热器两侧回路保留独立的介质归属，不通过图形分组自动合并。</div></div><div class="settings-section"><h3>物理量与单位</h3><div class="table-wrap"><table><thead><tr><th>物理量</th><th>工程显示</th><th>内部约定</th></tr></thead><tbody>${[['绝对压力','kPa / MPa','Pa'],['温度','°C','K'],['质量流量','kg/s','kg/s'],['比焓','kJ/kg','J/kg'],['密度','kg/m³','kg/m³'],['比容','m³/kg','m³/kg']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="muted" style="margin:12px 0 0;font-size:12px">密度与比容是不同物理量，独立命名与换算。</p></div>`;
  if(ui.settingsTab==='solver')return `<div class="settings-section"><h3>运行设置</h3><p>设置仿真时间、时间步长及停止条件。原型记录配置并演示控制流程。</p><div class="fields"><label class="field"><span>运行模式</span><select data-solver-field="mode">${option('dynamic','慢动态',p.solver.mode)}${option('steady','稳态',p.solver.mode)}</select></label><label class="field"><span>仿真时长</span><div class="field-unit"><input type="number" data-solver-field="duration" value="${p.solver.duration}" min="1" max="3600"><span>s</span></div></label><label class="field"><span>时间步长</span><div class="field-unit"><input type="number" data-solver-field="dt" value="${p.solver.dt}" min=".01" max="10" step=".01"><span>s</span></div></label><label class="field"><span>最大迭代次数</span><input type="number" data-solver-field="maxIter" value="${p.solver.maxIter}" min="5" max="500"></label></div></div><div class="settings-section"><h3>收敛判据</h3><p>质量与压力使用独立容差；数值设置需要在真实求解阶段验证。</p><div class="fields"><label class="field"><span>质量绝对容差</span><div class="field-unit"><input type="number" data-solver-field="massAtol" step="any" value="${p.solver.massAtol}" min="0"><span>kg/s</span></div></label><label class="field"><span>压力绝对容差</span><div class="field-unit"><input type="number" data-solver-field="pressureAtol" step="any" value="${p.solver.pressureAtol}" min="0"><span>Pa</span></div></label></div></div>`;
  if(ui.settingsTab==='appearance')return `<div class="settings-section"><h3>界面显示</h3><p>切换主题与画布辅助显示，原型会记住偏好。</p><div class="fields"><label class="field"><span>主题</span><select data-theme-select>${option('light','浅色',ui.theme)}${option('dark','深色',ui.theme)}</select></label><label class="field"><span>模块数值显示精度</span><select data-module-field="precision">${[2,4,6,8].map(n=>option(n,n+' 位小数',mod().precision)).join('')}</select></label></div><div style="margin-top:20px"><label class="check-label"><input type="checkbox" data-ui-toggle="pageGrid" ${ui.pageGrid?'checked':''}>显示画布点阵</label></div></div><div class="settings-section"><h3>窗口布局</h3><p>参数窗口可以移动、调整大小、置顶和收起。关闭查看窗口不会终止运行。</p>${btn('reset-windows','恢复窗口位置','Columns2')}${btn('nav','到画布查看','ArrowRight','data-route="workbench"','ghost')}</div><div class="settings-section"><h3>键盘操作</h3><div class="shortcut-grid" style="margin-top:15px">${shortcutMarkup()}</div></div>`;
  return `<div class="settings-section"><h3>原型保存</h3><p>保存当前浏览器中的项目、模块、型号、参数和配置。</p><div class="notice good">${icon('Database')}<span>${state.savedAt?'已保存原型草稿；再次保存会更新这份浏览器记录。':'当前使用内置示例，点击保存后记录你的编辑。'}</span></div><div class="row wrap" style="margin-top:18px">${btn('save','保存原型','Save','','primary')}${btn('export','导出原型 JSON','Download','data-format="prototype"')}${btn('import','导入原型 JSON','Upload')}</div></div><div class="settings-section"><h3>数据交换</h3><p>原型交换文件仅用于此设计版本，不直接修改正式项目工作区。</p><div class="row wrap">${btn('export','导出型号库','Database','data-format="models"')}${btn('export','导出变量表','Table2','data-format="variables"')}</div></div><div class="settings-section"><h3>恢复示例</h3><p>开始一轮新的原型体验前，可以先导出当前数据，再恢复示例。</p>${btn('reset-prototype','恢复内置示例','RotateCcw','','danger')}</div>`;
}
function shortcutMarkup(){return [['保存原型','Ctrl S'],['页面导航','Ctrl K'],['撤销 / 重做','Ctrl Z / Y'],['复制 / 粘贴设备','Ctrl C / V'],['删除选中对象','Delete'],['取消连线 / 关闭弹窗','Esc']].map(([label,key])=>`<div><span>${label}</span><kbd>${key}</kbd></div>`).join('');}
function renderHelp(){return `<div class="page-shell">${heading('页面导览与使用指南','先浏览所有页面，再用同一个调节阀示例走通完整流程。',btn('page-map','页面导航','LayoutDashboard')+btn('guided-demo','从模块开发开始','ArrowRight','','primary'))}<div class="journey">${[['01','定义模块','配置图形、端口和通路'],['02','准备参数','编辑库值并保存型号'],['03','搭建项目','插入设备、连接通路'],['04','调参运行','应用参数、运行与单步'],['05','观察结果','查看曲线、保存记录']].map(([n,t,d])=>`<div class="journey-step"><span class="step-number">${n}</span><strong>${t}</strong><p>${d}</p></div>`).join('')}</div><div class="section-title"><h2>所有页面</h2><span class="muted">${Object.keys(PAGE_META).length} 个页面 · ${EDITOR_TABS.length} 个模块编辑页签</span></div><div class="help-grid">${Object.entries(PAGE_META).filter(([id])=>id!=='help').map(([id,[name,i,desc]])=>`<article class="help-card">${icon(i)}<h3>${name}</h3><p>${desc}</p>${btn('nav','打开页面','ArrowUpRight',`data-route="${id}"`,'small')}</article>`).join('')}</div><div class="fields" style="margin-top:22px"><section class="panel"><div class="panel-head"><h3>三个不同的对象</h3></div><div class="panel-body stack"><p><strong>模块定义</strong><br><span class="muted">描述图形、端口、变量、通路和算法。</span></p><p><strong>设备型号</strong><br><span class="muted">保存一组命名参数，并保留版本。</span></p><p><strong>项目实例</strong><br><span class="muted">放在项目中的设备，可单独改参数。</span></p></div></section><section class="panel"><div class="panel-head"><h3>保存、应用与运行</h3></div><div class="panel-body stack"><p><strong>保存</strong>：保留当前编辑草稿。</p><p><strong>应用</strong>：检查差异，将参数写入当前设备。</p><p><strong>运行</strong>：推进项目运行并记录结果。</p><div class="notice">${icon('Info')}计算和编译流程均为原型演示；页面不会执行用户代码。</div></div></section></div><section class="panel" style="margin-top:20px"><div class="panel-head"><h3>常用快捷键</h3></div><div class="panel-body shortcut-grid">${shortcutMarkup()}</div></section></div>`;}
